describe('Delete Single Notification', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should successfully delete a single notification when delete button is clicked', () => {
    // Intercept the delete API call
    cy.intercept('DELETE /api/notifications/*').as('deleteNotification');

    // Verify notification list is visible and contains items
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Get the first notification item
    cy.get('[data-testid="notification-item"]').first().as('firstNotification');

    // Verify notification content
    cy.get('@firstNotification').should('contain', 'New message from John');
    cy.get('@firstNotification').should('contain', '2 minutes ago');

    // Click the delete button for the first notification
    cy.get('@firstNotification').find('[data-testid="delete-button"]').click();

    // Verify delete confirmation modal appears
    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');
    cy.get('[data-testid="delete-confirmation-modal"]').should('contain', 'Are you sure you want to delete this notification?');

    // Click confirm delete button
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Wait for the API call
    cy.wait('@deleteNotification');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Notification deleted successfully');

    // Verify the notification is removed from the list
    cy.get('[data-testid="notification-item"]').should('not.exist');
    cy.get('[data-testid="notification-list"]').should('be.visible');
  });

  it('should handle error when deleting a notification', () => {
    // Intercept the delete API call and mock an error response
    cy.intercept('DELETE /api/notifications/*', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('deleteNotificationError');

    // Verify notification list is visible
    cy.get('[data-testid="notification-list"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').should('have.length.greaterThan', 0);

    // Get the first notification item
    cy.get('[data-testid="notification-item"]').first().as('firstNotification');

    // Click the delete button
    cy.get('@firstNotification').find('[data-testid="delete-button"]').click();

    // Verify delete confirmation modal appears
    cy.get('[data-testid="delete-confirmation-modal"]').should('be.visible');

    // Click confirm delete button
    cy.get('[data-testid="confirm-delete-button"]').click();

    // Wait for the error API call
    cy.wait('@deleteNotificationError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to delete notification');

    // Verify notification still exists in the list
    cy.get('[data-testid="notification-item"]').should('be.visible');
    cy.get('[data-testid="notification-item"]').first().should('contain', 'New message from John');

    // Verify error button is available to retry
    cy.get('[data-testid="retry-delete-button"]').should('be.visible');
  });
});
